var t=`1249-escovitch-fish`;var n=`world-1249`;var a=`JM`;var s=`central-america-caribbean`;var r=4;var o=63;var l={en:`Escovitch Fish`,ua:`Риба есковіч`};var d={en:`Escovitch Fish is a dish from Jamaica featuring red snapper, lime juice, carrot, red bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Риба есковіч, страва кухні країни Ямайка з такими основними складниками: червоний луціан, сік лайма, морква, червоний солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var p=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`red-snapper`,800,`g`],[`lime-juice`,75,`ml`],[`table-salt`,8,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 14 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 14 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:14,i:[[`canola-oil`,150,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`carrot`,190,`g`],[`red-bell-pepper`,180,`g`],[`yellow-onion`,170,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:4,i:[[`white-vinegar`,110,`ml`],[`allspice-berries`,6,`pcs`]]}];var c={slug:t,id:n,country:`JM`,region:s,servings:4,minutes:63,title:l,text:d,steps:p};export{a as country,c as default,n as id,o as minutes,s as region,r as servings,t as slug,p as steps,d as text,l as title};